function New-KeystoneMutex {
    param([Parameter(Mandatory)][string]$Name)
    $safe = $Name -replace '[^A-Za-z0-9_-]', '_'
    try {
        [System.Threading.Mutex]::new($false, "Global\KeystoneOS-$safe")
    } catch [System.UnauthorizedAccessException] {
        # Global namespace can be denied by policy; a session-local mutex still gives
        # mutual exclusion between the scheduled task and the reconciler.
        [System.Threading.Mutex]::new($false, "Local\KeystoneOS-$safe")
    }
}

